import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'
import posthog from 'posthog-js'

import { userLogic } from 'scenes/userLogic'

import { UserType } from '~/types'

import { TodayIntroPane, todayPaneIntroKey } from './todayPaneIntros'
import { todayTourLogic } from './todayTourLogic'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPaneIntroLogicValues {
    tourActive: boolean // todayTourLogic
    user: UserType | null // userLogic
    dismissedLocally: Partial<Record<TodayIntroPane, true>>
    isIntroShown: (pane: TodayIntroPane) => boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPaneIntroLogicActions {
    updateHasSeenProductIntroFor: (
        productKey: string,
        value?: boolean | undefined
    ) => {
        productKey: string
        value: boolean
    } // userLogic
    dismissIntro: (pane: TodayIntroPane) => {
        pane: TodayIntroPane
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPaneIntroLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isIntroShown: (
            dismissedLocally: Partial<Record<TodayIntroPane, true>>,
            user: UserType | null,
            tourActive: boolean
        ) => (pane: TodayIntroPane) => boolean
    }
}

export type todayPaneIntroLogicType = MakeLogicType<
    todayPaneIntroLogicValues,
    todayPaneIntroLogicActions,
    Record<string, any>,
    todayPaneIntroLogicMeta
>

export const todayPaneIntroLogic = kea<todayPaneIntroLogicType>([
    path(['layout', 'today', 'todayPaneIntroLogic']),
    connect(() => ({
        values: [todayTourLogic, ['tourActive'], userLogic, ['user']],
        actions: [userLogic, ['updateHasSeenProductIntroFor']],
    })),
    actions({
        dismissIntro: (pane: TodayIntroPane) => ({ pane }),
    }),
    reducers({
        // Hides the intro at once. The user record confirms the dismissal once it reloads.
        dismissedLocally: [
            {} as Partial<Record<TodayIntroPane, true>>,
            {
                dismissIntro: (state, { pane }) => ({ ...state, [pane]: true }),
            },
        ],
    }),
    selectors({
        // The tour points at each intro, so it shows them again, unless the person dismisses one during the tour.
        isIntroShown: [
            (s) => [s.dismissedLocally, s.user, s.tourActive],
            (
                dismissedLocally: Partial<Record<TodayIntroPane, true>>,
                user: UserType | null,
                tourActive: boolean
            ): ((pane: TodayIntroPane) => boolean) =>
                (pane) =>
                    !dismissedLocally[pane] &&
                    (tourActive || !user?.has_seen_product_intro_for?.[todayPaneIntroKey(pane)]),
        ],
    }),
    listeners(({ actions }) => ({
        dismissIntro: ({ pane }) => {
            actions.updateHasSeenProductIntroFor(todayPaneIntroKey(pane))
            // pinned: analytics event name and property. Renaming them breaks dashboards.
            posthog.capture('today pane intro dismissed', { pane })
        },
    })),
])
